21	  const { courseKey } = useParams();
22	  const [courseDetail, setCourseDetail] = useState<any>(null);
23	  const [selectedLessonIds, setSelectedLessonIds] = useState<Set<string>>(
24	    new Set(),
25	  );
26	  const [dateSortOrder, setDateSortOrder] = useState<"asc" | "desc">("asc");
27	
28	  const getSemester = (courseKey: string) => {
29	    if (!courseKey) return "";
30	    const semesterCode = courseKey.slice(0, 4);
31	    return `${semesterCode.slice(0, 3)}-${semesterCode.slice(3)}`;
32	  };
33	
34	  const formatWeekNumber = (weekNumber: number) => `第${weekNumber}週`;
35	
36	  const formatDate = (dateString: string) => {
37	    if (!dateString) return "";
38	    const parts = dateString.split("-");
39	    if (parts.length < 3) return dateString;
40	    return `${parts[1]}月${parts[2].substring(0, 2)}日`;
41	  };
42	
43	  const formatCourseDetail = (data: any, key: string) => {
44	    return {
45	      ...data,
46	      semester: getSemester(key),
47	      enrolled: data.enrolled_count ?? data.enrolled,
48	      capacity: data.max_capacity ?? data.capacity,
49	      course_schedule: formatCourseSchedule(data.course_schedule),
50	      course_schedule_time: formatCourseScheduleTime(data.course_schedule),
51	      lessons: (data.lessons || []).map((lesson: any) => {
52	        const status = lesson.status;
53	        return {
54	          ...lesson,
55	          status,
56	          processText:
57	            lesson.processText ??
58	            (status === "analyzing" ? "資料分析中" : undefined),
59	          errorText:
60	            lesson.errorText ??
61	            (status === "error" ? "請聯絡資訊組" : undefined),
62	        };
63	      }),
64	    };
65	  };
66	
67	  const getMockCourseDetail = (key: string) => {
68	    const decodedKey = decodeURIComponent(key);
69	    return mockLessons.find(
70	      (lesson: any) => decodeURIComponent(lesson.course_key) === decodedKey,
71	    );
72	  };
73	
74	  const fetchLessons = async (key: string) => {
75	    try {
76	      const basePath = process.env.NEXT_PUBLIC_BASE_PATH || "";
77	      const baseUrl = `${basePath}/api`;
78	
79	      const response = await fetch(
80	        `${baseUrl}/courses/${encodeURIComponent(key)}/lessons`,
81	        {
82	          method: "GET",
83	          headers: { accept: "*/*" },
84	        },
85	      );
86	
87	      if (!response.ok) throw new Error("Failed to fetch lessons from API");
88	
89	      const resBody = await response.json();
90	      setCourseDetail(formatCourseDetail(resBody, key));
91	      console.log("Fetched lessons from API");
92	    } catch (error) {
93	      console.error(error);
94	      // const mockLessonsData = getMockCourseDetail(key);
95	      // setCourseDetail(
96	      //   mockLessonsData ? formatCourseDetail(mockLessonsData, key) : null,
97	      // );
98	    }
99	  };
100	
101	  useEffect(() => {
102	    if (!courseKey || courseKey === "undefined") return;
103	    fetchLessons(String(courseKey));
104	    setSelectedLessonIds(new Set());
105	    setDateSortOrder("asc");
106	  }, [courseKey]);
107	
108	  const lessons = courseDetail?.lessons || [];
109	  const sortedLessons = useMemo(
110	    () =>
111	      [...lessons].sort((a: any, b: any) => {
112	        const dateA = a.lesson_date ?? "";
113	        const dateB = b.lesson_date ?? "";
114	        return dateSortOrder === "asc"
115	          ? dateA.localeCompare(dateB)
116	          : dateB.localeCompare(dateA);
