120	
121	  const toggleDateSort = () => {
122	    setDateSortOrder((prev) => (prev === "asc" ? "desc" : "asc"));
123	  };
124	  const selectedCount = selectedLessonIds.size;
125	  const allLessonsSelected =
126	    lessons.length > 0 &&
127	    lessons.every((lesson: any) => selectedLessonIds.has(lesson.lesson_id));
128	  const someLessonsSelected = selectedCount > 0 && !allLessonsSelected;
129	
130	  const toggleLessonSelection = (lessonId: string) => {
131	    setSelectedLessonIds((prev) => {
132	      const next = new Set(prev);
133	      if (next.has(lessonId)) {
134	        next.delete(lessonId);
135	      } else {
136	        next.add(lessonId);
137	      }
138	      return next;
139	    });
140	  };
141	
142	  const toggleAllLessons = () => {
143	    if (allLessonsSelected) {
