172	              showArrow={false}
173	              triggerMode="hover"
174	            >
175	              <Link
176	                href="/course"
177	                className="relative group w-8 h-8 bg-white rounded-full flex items-center justify-center text-gray-90"
178	              >
179	                <ArrowLeft size={18} />
180	              </Link>
181	            </Tooltip>
182	            <div className="flex-1">
183	              <h1 className="headline-3-reg text-gray-90 mb-2 leading-snug">
184	                課程週覽
185	              </h1>
186	            </div>
187	          </div>
188	
189	          <div className="flex flex-col gap-2">
190	            <h1 className="headline-1-sb text-gray-90 flex items-center gap-2">
191	              {courseDetail?.course_name}
192	            </h1>
193	            <div className="flex flex-wrap gap-2">
