233	                    <Checkbox
234	                      checked={allLessonsSelected}
235	                      // indeterminate={someLessonsSelected}
236	                      onChange={toggleAllLessons}
237	                      onClick={(e) => e.stopPropagation()}
238	                    />
239	                  </div>
240	                </th>
241	
242	                <th className="py-5 px-0 body-1-reg text-gray-70 w-[240px] text-left">
243	                  <div className="bg-[rgba(6,45,65,0.05)] h-12 flex items-center pr-4 lg:pl-6">
244	                    <div className="flex items-center gap-1">
245	                      日期{" "}
246	                      <Tooltip
247	                        content={
248	                          dateSortOrder === "asc"
249	                            ? "由舊到新排序"
250	                            : "由新到舊排序"
251	                        }
252	                        showQuestionMark={false}
253	                        showArrow={false}
254	                        triggerMode="hover"
255	                      >
256	                        <button
257	                          onClick={toggleDateSort}
258	                          className="cursor-pointer"
259	                        >
260	                          <div className="w-[32px] h-[32px] rounded-full flex items-center justify-center hover:bg-[rgba(6,45,65,0.05)]">
261	                            <Image
262	                              src={
263	                                dateSortOrder === "asc"
264	                                  ? "/icon/function/icon_sorting-down.svg"
265	                                  : "/icon/function/icon_sorting-up.svg"
266	                              }
267	                              alt={
268	                                dateSortOrder === "asc"
269	                                  ? "由舊到新排序"
270	                                  : "由新到舊排序"
271	                              }
272	                              width={24}
273	                              height={24}
274	                            />
275	                          </div>
276	                        </button>
277	                      </Tooltip>
278	                    </div>
279	                  </div>
280	                </th>
281	
282	                <th className="py-5 px-0 body-1-reg text-gray-70 text-left">
283	                  <div className="bg-[rgba(6,45,65,0.05)] h-12 flex items-center px-2 lg:px-6">
284	                    課程進度
285	                  </div>
286	                </th>
287	
288	                <th className="py-5 pl-0 pr-5 body-1-reg text-gray-70 w-[184px] min-w-[184px] max-w-[184px] text-left">
289	                  <div className="bg-[rgba(6,45,65,0.05)] h-12 flex items-center pl-4 pr-5 lg:pr-6 rounded-r-[12px]">
290	                    投入程度
291	                  </div>
292	                </th>
293	              </tr>
294	              {/* header(<1024px) */}
295	              <tr className="flex lg:hidden bg-[rgba(6,45,65,0.05)] rounded-[12px] p-3 mb-2 items-center gap-3">
296	                <th className="w-6 flex items-center justify-center">
297	                  <Checkbox
298	                    checked={allLessonsSelected}
299	                    indeterminate={someLessonsSelected}
300	                    onChange={toggleAllLessons}
301	                    onClick={(e) => e.stopPropagation()}
302	                  />
303	                </th>
304	                <th className="body-1-reg text-gray-70 flex items-center gap-1">
305	                  <div className="flex items-center gap-1">
306	                    日期{" "}
307	                    <Tooltip
308	                      content={
309	                        dateSortOrder === "asc"
310	                          ? "由舊到新排序"
311	                          : "由新到舊排序"
312	                      }
313	                      showQuestionMark={false}
314	                      showArrow={false}
315	                      triggerMode="hover"
316	                    >
317	                      <button
318	                        onClick={toggleDateSort}
319	                        className="cursor-pointer"
320	                      >
321	                        <div className="w-[32px] h-[32px] rounded-full flex items-center justify-center hover:bg-[rgba(6,45,65,0.05)]">
322	                          <Image
323	                            src={
324	                              dateSortOrder === "asc"
325	                                ? "/icon/function/icon_sorting-down.svg"
326	                                : "/icon/function/icon_sorting-up.svg"
327	                            }
328	                            alt={
329	                              dateSortOrder === "asc"
330	                                ? "由舊到新排序"
331	                                : "由新到舊排序"
332	                            }
333	                            width={24}
334	                            height={24}
335	                          />
336	                        </div>
337	                      </button>
338	                    </Tooltip>
339	                  </div>
340	                </th>
341	              </tr>
342	            </thead>
343	
344	            <tbody className="block lg:table-row-group">
345	              {sortedLessons.map((lesson: any) => (
346	                <tr
