348	                  className="cursor-pointer hover:bg-[rgba(6,45,65,0.05)] transition-colors 
349	                       flex flex-row items-center gap-4 py-4 lg:py-0 lg:table-row border-b border-[rgba(0,0,0,0.1)]"
