451	
452	function StatusContent({
453	  status,
454	  errorText,
455	  processText,
456	  lessonId,
457	}: {
458	  status: string;
459	  errorText?: string;
460	  processText?: string;
461	  lessonId?: string;
462	}) {
463	  if (status === "completed" && lessonId) {
464	    return <EngagementMiniChart lessonId={lessonId} />;
465	  }
466	  if (status === "error") {
467	    return (
468	      <div className="flex items-center justify-start gap-1 text-danger-50 bg-danger-10 px-3 py-1.5 rounded-lg body-1-reg w-fit whitespace-nowrap">
469	        <Image
470	          src="/icon/function/icon_warning_filled.svg"
471	          alt="Error"
472	          width={16}
473	          height={16}
474	        />
475	        {errorText}
476	      </div>
477	    );
478	  }
479	  if (status === "analyzing") {
480	    return (
481	      <div className="flex items-center justify-start gap-1 text-warning-50 bg-warning-10 px-3 py-1.5 rounded-lg body-1-reg w-fit whitespace-nowrap">
482	        <Image
483	          src="/icon/function/icon_in-progress-yellow.svg"
484	          alt="In Progress"
485	          width={16}
486	          height={16}
487	        />
488	        {processText}
489	      </div>
490	    );
491	  }
492	  return <div className="h-12" />;
493	}
494	
495	function Tag({ text, hint }: { text: string; hint: string }) {
496	  return (
497	    <Tooltip
498	      content={hint}
499	      showQuestionMark={false}
500	      showArrow={false}
501	      triggerMode="hover"
502	    >
503	      <span className="px-3 py-2 bg-[rgba(6,45,65,0.05)] text-gray-90 body-1-reg rounded-lg block whitespace-nowrap">
504	        {text}
505	      </span>
506	    </Tooltip>
507	  );
508	}
