35	  const fetchVideo = async () => {
36	    try {
37	      throw new Error("Failed to get video/audio from API");
38	    } catch (error) {
39	      console.error(error);
40	      const basePath = process.env.NEXT_PUBLIC_BASE_PATH || "";
41	      const path = `${mockAudioMapping[lessonId as keyof typeof mockAudioMapping]}`;
42	      if (path !== "undefined") {
43	        const mockAudioPath = `${basePath}${path}`;
44	        setVideoUrl(mockAudioPath);
45	        console.log("Fetched video/audio from mock data:", mockAudioPath);
46	      } else {
47	        console.error(
48	          `No mock video/audio data found for lessonId: ${lessonId}`,
49	        );
