33	            .Select(g => new
34	            {
35	                CourseKey = g.Key,
36	                Total = g.Count(),
37	                Completed = g.Count(r => r.IsScreenshotGenerated)
38	            })
39	            .ToDictionaryAsync(x => x.CourseKey, x => x);
